package app

// Original reflective prompts, not translations of a proprietary report.
// Labels describe traditional symbolic themes; none predict traits or events.
var gateThemes = map[int]theme{
	1:  {"Yaratıcı ifade", "Kendi ifade biçimini bulmak ve bir fikre özgün bir şekil vermek teması. Sonucun beğenilmesi kadar üretim sürecinde kendine alan açmayı da gözlemleyebilirsin.", "Bir fikri önce kendin için üret; değerlendirmeyi daha sonra yap.", "İfade ederken bana ait olan kısmı duyabiliyor muyum?"},
	2:  {"Yön ve alıcılık", "Bir yönün oluşmasını dinlemek ve kaynaklarla yönü bir araya getirmek teması. Sürekli kontrol etmeye çalışmadan neye açık olduğunu fark etmek bir gözlem alanı olabilir.", "Hedefini ve o hedefe götürecek gerçek kaynakları ayrı ayrı yaz.", "Bu yön benim için anlamlı mı?"},
	3:  {"Yeni bir düzene geçiş", "Başlangıçta dağınık görünen bir şeyin zamanla bir düzene dönüşmesi teması. İlk denemenin kusursuz olmasını beklemeden, henüz şekillenmemiş aşamaya alan açmayı inceleyebilirsin.", "Bir başlangıcı küçük adımlara böl; ilk adım için yeterli koşulları belirle.", "Henüz oluşmakta olan bu süreçten ne bekliyorum?"},
	4:  {"Cevap ve açıklama", "Sorulara anlaşılır bir açıklama oluşturma teması. Bir cevabın makul görünmesi ile sınanmış olması arasındaki farkı gözetmek önem kazanır.", "Bir açıklamanın hangi kanıta dayandığını ve nerede varsayım içerdiğini belirt.", "Bu cevap hangi soruyu gerçekten karşılıyor?"},
	5:  {"Ritim", "Tekrarlayan alışkanlıklar ve günlük ritim teması. Rutinlerin destekleyici mi, katı mı olduğunu gözlemlemek için kullanılabilir.", "Bir hafta boyunca çalışma ve dinlenme ritmini kaydet.", "Hangi düzen beni destekliyor?"},
	6:  {"Yakınlıkta sınır", "Duygusal yakınlaşmada sınırlar ve etkileşim teması. Bir ilişkide yakın olmak ile her şeye açık olmak arasındaki farkı konuşmak için bir başlangıç olabilir.", "Bir ilişkide rahat olduğun ve olmadığın sınırları açıkça ifade et.", "Yakınlık kurarken sınırlarım da görünür mü?"},
	7:  {"Ortak yön", "Bir grubun yönüne katkı verme teması. Yön önermekle herkesin yerine karar vermeyi ayırmayı gözlemleyebilirsin.", "Bir ortak hedefte kimin hangi kararda söz sahibi olduğunu netleştir.", "Bu yönü birlikte mi belirliyoruz?"},
	8:  {"Katkıyı paylaşmak", "Kendine özgü bir katkıyı görünür kılma teması. Başkasının yöntemini tekrarlamak yerine kendi katkının ne olduğunu adlandırabilirsin.", "Bir çalışmaya kattığın somut farklılığı bir cümlede anlat.", "Burada benim katkım ne?"},
	9:  {"Ayrıntıya odaklanmak", "Dikkati küçük bir parçaya yöneltme teması. Bir ayrıntıya yoğunlaşırken bütünün amacını kaybetmemeyi gözlemleyebilirsin.", "Tek bir alt görev seç ve bitirme ölçütünü belirle.", "Bu ayrıntı bütüne hizmet ediyor mu?"},
	10: {"Kendinle uyumlu davranış", "Kendi değerlerinle uyumlu davranma teması. Bir beklentiye uyarken kendi tutumunu kaybedip kaybetmediğini düşünmek için kullanılabilir.", "Bir gün içinde kendinle uyumlu hissettiğin bir davranışı yaz.", "Bu davranış değerlerimle uyuşuyor mu?"},
	11: {"Fikirler", "Zihinde beliren fikirler ve imgeler teması. Bir fikrin değerli olması, hepsini uygulaman gerektiği anlamına gelmez.", "Fikirlerini bir yerde topla; uygulama seçimini tip ve otorite bölümünle birlikte değerlendir.", "Bu fikir paylaşılmak mı, uygulanmak mı istiyor?"},
	12: {"İfadenin zamanı", "Duygu ve sözün uygun zamanda buluşması teması. Bir şeyi ifade etmeyi istemekle uygun paylaşım alanının bulunması arasındaki farkı gözlemleyebilirsin.", "Paylaşmak istediğin bir cümleyi yaz; uygun konuşma zamanını ayrıca seç.", "Şimdi ifade etmeye ve dinlenmeye alan var mı?"},
	13: {"Dinlemek ve tanıklık", "Başkasının deneyimine kulak verme ve anlatılanı taşıma teması. Dinlemek, başkasının yükünü bütünüyle üstlenmek zorunda olmak değildir.", "Dinlerken karşı tarafın paylaşım mı, çözüm mü istediğini sor.", "Gerçekten dinliyor muyum, hemen çözüm mü üretiyorum?"},
	14: {"Kaynakları yönlendirmek", "Emek, beceri ve kaynakların bir yönde kullanılması teması. Bu yerleşim maddi başarı veya zenginlik garantisi vermez.", "Kaynaklarını nereye ayırdığını ve hangi amaca hizmet ettiğini yaz.", "Emeğim anlamlı bulduğum yöne gidiyor mu?"},
	15: {"Farklı ritimlere alan", "İnsanların ve yaşamın farklı tempolarına alan açma teması. Kendi ritminle çevrendekilerin ritmini aynı olmak zorunda görmeden inceleyebilirsin.", "Bir ortak işte tempo farklarını açıkça konuş.", "Farklı bir ritme alan açarken kendi ihtiyacımı koruyor muyum?"},
	16: {"Beceriyi geliştirmek", "Tekrar, uygulama ve beceri edinme teması. Heves ile yeterlilik arasındaki mesafeyi küçük çalışmalara bölmek yardımcı olabilir.", "Bir beceri için kısa ve düzenli bir uygulama planı yap.", "Hangi tekrar bana gerçek gelişim sağlıyor?"},
	17: {"Görüş oluşturmak", "Bilgiyi bir görüş veya düzenli çerçeveye dönüştürme teması. Bir görüşü kesin olguyla karıştırmadan paylaşmayı gözlemleyebilirsin.", "Görüşünün dayanaklarını ve değişebileceği koşulları yaz.", "Bu görüş hangi bilgiye dayanıyor?"},
	18: {"İyileştirme", "Bir süreçte neyin daha iyi yapılabileceğini fark etme teması. Geri bildirimin yararı, karşı tarafın talebi ve somut değişiklik önerisiyle artabilir.", "Bir eleştiriyi uygulanabilir bir öneriye dönüştür.", "Bu geri bildirim kime ve hangi konuda yarar sağlıyor?"},
	19: {"İhtiyaçları fark etmek", "Kendinin ve çevrenin ihtiyaçlarına duyarlılık teması. Bir ihtiyacı fark etmekle onu tek başına karşılamak arasındaki sınırı gözlemleyebilirsin.", "İhtiyacı, sorumluluğu ve sunabileceğin katkıyı ayır.", "Bu ihtiyaç kimin sorumluluğunda?"},
	20: {"Şimdiki anın ifadesi", "İçinde bulunulan anı fark etmek ve dile getirmek teması. Anlık bir ifade, bütün koşulların değerlendirildiği bir karar olmak zorunda değildir.", "Bir olayda gözlemlediğini, ona eklediğin yorumdan ayır.", "Şu anda gerçekten ne oluyor?"},
	21: {"Yönetim ve sınırlar", "Kaynakları yönetme ve sorumluluk alanını belirleme teması. Kontrol etmeye çalıştığın alanla gerçekten yetkili olduğun alanı ayırabilirsin.", "Bir sorumlulukta yetki ve hesap verme sınırlarını konuş.", "Burada neyi gerçekten yönetebilirim?"},
	22: {"Sosyal açıklık", "Duygusal halin sosyal karşılaşmaya yansıması teması. İletişim için hazır olup olmadığını fark etmek bir gözlem alanıdır.", "Bir görüşmeden önce nasıl bir katılıma hazır olduğunu ifade et.", "Bu karşılaşmaya şu anda ne kadar açık hissediyorum?"},
	23: {"Karmaşık fikri sadeleştirmek", "Bir içgörüyü anlaşılır sözlere dönüştürme teması. Basit anlatım için dinleyenin bildiği noktayı dikkate alabilirsin.", "Bir fikri teknik dil kullanmadan kısa bir örnekle anlat.", "Dinleyen kişi neyi anlamak için ek bağlama ihtiyaç duyuyor?"},
	24: {"Geri dönüp düşünmek", "Bir düşünceye tekrar dönerek anlam arama teması. Yararlı yeniden değerlendirme ile aynı yerde dönmeyi ayırmayı gözlemleyebilirsin.", "Yeni bilgi olmadan tekrar ettiğin düşünceye ara ver; neyin eksik olduğunu yaz.", "Bu tekrar yeni bir anlayış getiriyor mu?"},
	25: {"Açık yüreklilik", "Deneyime önceden hüküm vermeden yaklaşma teması. Açıklıkla kişisel sınırları birlikte tutmak üzerine düşünebilirsin.", "Bir kişiyi tek bir olayla tanımlamadan önce bağlamı dinle.", "Açık kalırken sınırlarımı da koruyor muyum?"},
	26: {"İkna ve sunum", "Bir şeyi etkili biçimde sunma teması. Sunumun gücüyle doğruluk ve verilen sözün kapsamını birlikte değerlendirebilirsin.", "Bir iddiayı paylaşırken kanıtını ve sınırını belirt.", "Anlatımım gerçek katkıyla örtüşüyor mu?"},
	27: {"Bakım ve destek", "Beslemek, desteklemek ve sorumluluk alma teması. Başkasına bakım verirken kendi kapasiteni unutmayı gözlemleyebilirsin.", "Sunabileceğin desteği süre ve kapsamıyla belirle.", "Destek verirken benim ihtiyacım da karşılanıyor mu?"},
	28: {"Anlamlı mücadele", "Eforun anlamı ve ne uğruna mücadele edildiği teması. Her zorluk sürdürülmeye değer olmak zorunda değildir.", "Bir zorluk için harcadığın emeğin hangi değere hizmet ettiğini yaz.", "Bu mücadeleyi anlamlı kılan ne?"},
	29: {"Katılmak ve söz vermek", "Bir deneyime evet deme ve katılımı sürdürme teması. Her teklifi kabul etmekle gerçekten katılmak istemeyi ayırmak önem kazanır.", "Bir evetten önce kapsamı ve sürdürebileceğin koşulları netleştir.", "Bu sözü hangi kapasiteyle veriyorum?"},
	30: {"Arzu ve deneyim", "Bir deneyime yönelik arzu ve beklenti teması. İstemek ile sonucun nasıl olacağını kontrol etmek farklıdır.", "Bir beklentinin yanında kontrol edemediğin koşulları da yaz.", "Deneyimi mi istiyorum, belirli bir sonucu mu?"},
	31: {"Etkili yönlendirme", "Bir grubun duyduğu ve kabul ettiği yönlendirme teması. Sesini duyurmak ile ortak rıza oluşturmak arasındaki farkı gözlemleyebilirsin.", "Bir yön önerirken dinleyenlerin görüşünü sor.", "Bu yönlendirme gerçekten karşılık buluyor mu?"},
	32: {"Süreklilik", "Neyin korunup sürdürülebileceğini ayırt etme teması. Tanıdık bir düzeni korumakla işe yarayanı korumayı ayırabilirsin.", "Bir yöntemin değerini bugünkü sonuçlarıyla değerlendir.", "Neyi korumak gerçekten yararlı?"},
	33: {"Geri çekilme ve deneyimi sindirme", "Yaşananı anlamlandırmak için mesafe ve mahremiyet teması. Her deneyimi hemen anlatmak zorunda olmadığını hatırlatabilir.", "Bir olaydan sonra paylaşmadan önce kendine düşünme zamanı ver.", "Bu deneyimi paylaşmaya hazır mıyım?"},
	34: {"Güç ve uygulama", "Bir işe ayrılan güç ve doğrudan uygulama teması. Güçlü katılım isteği, işin uygunluğunu ve sonuçlarını tek başına belirlemez.", "Eforunu hangi somut işe ayıracağını seç ve otorite bölümüne göre değerlendir.", "Bu güç gerçekten seçtiğim işe mi gidiyor?"},
	35: {"Değişim ve yeni deneyim", "Yeni bir deneyime geçmek ve yaşanandan öğrenmek teması. Yenilik arzusuyla mevcut işi tamamlama ihtiyacını birlikte gözlemleyebilirsin.", "Bir değişiklik öncesinde neyin eksik olduğunu somutlaştır.", "Değişim hangi ihtiyaca karşılık geliyor?"},
	36: {"Belirsiz deneyimde öğrenmek", "Alışılmadık bir deneyimde duygusal yoğunluk ve öğrenme teması. Bu kapı bir kriz yaşanacağını öngörmez.", "Yeni bir deneyimde destek, zaman ve gerçek beklentileri önceden konuş.", "Bu yeni durum için neye ihtiyacım var?"},
	37: {"Karşılıklı destek", "Yakın çevrede sıcaklık, anlaşma ve karşılıklılık teması. Bağlılık ile üstlenilen yükün dengesini inceleyebilirsin.", "Bir ortaklıkta verilen ve alınan desteği açıklaştır.", "Bu anlaşma karşılıklı mı?"},
	38: {"Değer verdiğini savunmak", "Bir konunun uğruna durmaya değer olup olmadığını seçme teması. Karşı çıkmak tek başına bir amaç olmak zorunda değildir.", "Savunduğun şeyin değerini bir cümlede ifade et.", "Bu itiraz hangi değeri koruyor?"},
	39: {"Duygusal hareket yaratmak", "Bir sorunun veya karşılaşmanın duygusal bir şeyi görünür kılması teması. Başkasının sınırlarını zorlamak bu temanın zorunlu bir davranışı değildir.", "Zor bir konuyu açarken konuşmaya rıza ve uygun zaman iste.", "Bu soru açıklık mı getiriyor, gereksiz gerilim mi?"},
	40: {"Emek ve dinlenme", "Sorumluluk üstlenme ile kendi zamanına çekilme teması. Bir katkının bedelini ve toparlanma ihtiyacını açık konuşabilirsin.", "Bir işin karşılığını ve sonrasındaki dinlenme alanını belirle.", "Verdiğim emeğin yanında dinlenmeye de yer var mı?"},
	41: {"Olasılığı hayal etmek", "Bir deneyimin başlamasına yönelik hayal ve istek teması. Hayal kurmakla gerçek kapasiteyi planlamak birlikte ele alınabilir.", "Bir hayalden bugün uygulanabilir tek bir küçük adım seç.", "Bu olasılığın ilk gerçek adımı ne?"},
	42: {"Süreci tamamlamak", "Bir döngünün gelişmesi ve uygun noktada tamamlanması teması. Sürdürme ile bitirme arasındaki ölçütleri gözlemleyebilirsin.", "Bir proje için tamamlanmış sayılma koşulunu yaz.", "Bu döngü hangi noktada tamamlanmış olur?"},
	43: {"İçgörü", "Bir konuyu farklı biçimde görme teması. Bir içgörünün sana anlaşılır gelmesi, başkasının bağlamı bildiği anlamına gelmez.", "Yeni fark ettiğin şeyi önce bir örnekle sınayıp anlat.", "Bu içgörüyü nasıl anlaşılır kılabilirim?"},
	44: {"Örüntüyü fark etmek", "Geçmiş deneyimlerden bir örüntüyü tanıma teması. Benzerlik fark etmek, aynı sonucun kesinlikle tekrarlanacağı anlamına gelmez.", "Bir benzerliğin yanına bugünkü koşullardaki farkları da yaz.", "Gerçek bir örüntü mü görüyorum, eski deneyimi mi yansıtıyorum?"},
	45: {"Ortak kaynak", "Bir topluluğun kaynaklarını paylaşma ve düzenleme teması. Kaynak üzerinde söz sahibi olmakla şeffaflık ve ortak sorumluluk birlikte ele alınabilir.", "Ortak bir kaynak için kullanım ve paylaşım koşullarını açıklaştır.", "Kaynaklar kimin ihtiyacına göre dağıtılıyor?"},
	46: {"Deneyime katılmak", "Yaşamı bedensel deneyim içinde keşfetme teması. Bu sembolik tema bedensel özellik veya sağlık sonucu çıkarmaz.", "Bir deneyimde yalnız sonucu değil süreçte fark ettiklerini de kaydet.", "Bu deneyimde gerçekten bulunabiliyor muyum?"},
	47: {"Yaşananı anlamlandırmak", "Geçmişte dağınık görünen izlenimleri bir anlayışa dönüştürme teması. Her anıya hemen bir anlam bulmak zorunda değilsin.", "Bir olayın gözlemlerini yaz; anlamını daha sonra yeniden değerlendir.", "Anlam henüz oluşmadıysa buna alan açabilir miyim?"},
	48: {"Derinlik", "Bir konuda derine inme ve yeterli bir çözüm arama teması. Yetersizlik hissiyle gerçekten eksik olan bilgi arasındaki farkı inceleyebilirsin.", "Bildiğin, çalışman gereken ve yardım alabileceğin alanları ayır.", "Yeterli olmak için hangi bilgi gerçekten eksik?"},
	49: {"İlkeler ve kabul sınırı", "Bir ilişki veya düzende hangi koşulların kabul edilebilir olduğu teması. İlkeyi açıkça söylemek, sonradan biriken beklentiyi azaltabilir.", "Önemli bir ilişkide vazgeçilmez sınırlarını konuş.", "Bu ilke herkes tarafından anlaşılıyor mu?"},
	50: {"Değerler ve sorumluluk", "Bir topluluğu koruyan değerler ve sorumluluk teması. Kendi değerlerinle devraldığın kuralları ayırmayı gözlemleyebilirsin.", "Bir kuralın hangi ihtiyacı koruduğunu ve bugün işe yarayıp yaramadığını yaz.", "Bu sorumluluğu bilinçli olarak mı üstleniyorum?"},
	51: {"Sarsıcı başlangıç", "Alışılmış bir çerçevenin dışına çıkma ve kendini sınama teması. Bu kapı kaza veya beklenmedik olay öngörmez.", "Bir meydan okumada isteğini ve gerçek koşulları ayrı değerlendir.", "Bu deneme benim için anlamlı mı, yalnızca kendimi ispat mı?"},
	52: {"Durmak ve yoğunlaşmak", "Hareketsizlik içinde dikkati bir noktada tutma teması. Durmak, hiçbir şey yapmamakla aynı deneyim olmayabilir.", "Bir işe başlamadan önce kısa bir odaklanma alanı oluştur.", "Bu duraklama dikkatim için ne sağlıyor?"},
	53: {"Bir döngüyü başlatmak", "Yeni bir gelişim sürecinin başlangıcı teması. Başlama isteğini sürdürebilecek koşullarla birlikte değerlendirebilirsin.", "Yeni bir işin ilk adımı kadar devam kaynaklarını da planla.", "Başlattığım şeyi geliştirmek için alan var mı?"},
	54: {"Gelişme isteği", "İlerleme ve emek yoluyla koşulları dönüştürme teması. Harita statü veya başarı garantisi vermez.", "İlerleme hedefini kendi değerlerinle ve gerçek bir ölçütle tanımla.", "İlerlemek benim için ne demek?"},
	55: {"Duygusal anlam ve bolluk hissi", "Deneyimin duygu haline göre anlam kazanması teması. Bolluk burada bir maddi sonuç tahmini değildir.", "Benzer bir olayı farklı duygu hallerinde nasıl yorumladığını kaydet.", "Bugünkü duygu halim neyi görmemi kolaylaştırıyor veya zorlaştırıyor?"},
	56: {"Deneyimi anlatmak", "Bir yaşantıyı hikâye ve anlatı yoluyla paylaşma teması. Anlatılan örnek ile herkes için geçerli bir kural arasındaki farkı belirtmek yararlı olabilir.", "Bir deneyimi anlatırken ne yaşandığını ve ne öğrendiğini ayır.", "Bu hikâye hangi deneyimi görünür kılıyor?"},
	57: {"İnce farkındalık", "Bulunulan andaki ince işaretleri fark etme teması. Bir izlenimin doğruluğunu harita tek başına doğrulamaz.", "Fark ettiğin işareti somut koşullarla karşılaştır.", "Şu anda dikkatimi çeken somut işaret ne?"},
	58: {"Canlılık ve iyileştirme isteği", "Bir şeyi daha iyi hale getirme isteği teması. Geliştirme hevesinin kendine ve başkalarına sürekli eleştiri olarak yansımasını gözlemleyebilirsin.", "Bir iyileştirme önerisinin yanında zaten çalışan kısmı da belirt.", "Bu gelişim isteği nerede yararlı bir katkıya dönüşüyor?"},
	59: {"Yakınlaşma", "İnsanlar arasındaki mesafeyi azaltma ve yakınlık kurma teması. Bu tema cinsel davranış veya ilişki sonucunu belirlemez; karşılıklı rıza ve sınırlar esastır.", "Yakınlık istediğinde karşı tarafın isteğini ve sınırını sor.", "Bu yakınlaşma iki taraf için de uygun mu?"},
	60: {"Sınır içinde yenilik", "Koşulların sınırlarını kabul ederek değişime alan açma teması. Her sınır engel olmak zorunda değildir; bazıları uygulanabilir bir çerçeve sağlar.", "Değiştirebildiğin ve şu anda değiştiremediğin koşulları ayır.", "Bu çerçevede hangi küçük değişiklik mümkün?"},
	61: {"İçsel soru", "Bir şeyin özünü veya nedenini anlama isteği teması. Her sorunun kesin bir cevabı olacağı varsayımını inceleyebilirsin.", "Bir büyük soruya cevap aramak kadar cevaplanmamış haliyle durmaya da alan ver.", "Bu soru merakımı mı besliyor, baskımı mı artırıyor?"},
	62: {"Ayrıntılı anlatım", "Bir düşünceyi somut ayrıntılarla açıklama teması. Dinleyenin ihtiyacına göre ayrıntı miktarını seçebilirsin.", "Bir açıklamayı önce ana fikir, sonra gerekli ayrıntı şeklinde düzenle.", "Hangi ayrıntı anlaşılmayı gerçekten kolaylaştırıyor?"},
	63: {"Sorgulama", "Bir açıklamayı soru ve karşılaştırmayla sınama teması. Şüpheyi belirli bir soruya dönüştürmek, sürekli belirsizlikten daha yararlı olabilir.", "Bir şüphe için hangi kanıtın yeterli olacağını belirle.", "Bu şüpheyi hangi bilgiyle sınayabilirim?"},
	64: {"Dağınık izlenimler", "Henüz anlamı oluşmamış anı ve imgeler teması. Dağınık izlenimlerden hemen bir sonuç çıkarmadan beklemeyi gözlemleyebilirsin.", "İzlenimlerini yorumlamadan yaz ve bir süre sonra yeniden oku.", "Bütün parçaları hemen birleştirmem gerekiyor mu?"},
}

var channelThemes = map[string]theme{
	"1-8":   {"Yaratıcı katkı", "Yaratıcı ifade ile katkıyı paylaşma temalarının bağlantısı. Özgün bir iş üretmek ve o işi uygun bir ortamda görünür kılmak üzerine düşünülebilir.", "Bir çalışmanın sana özgü katkısını anlat ve paylaşılacak ortamı seç.", "Kendi ifade biçimim nerede karşılık buluyor?"},
	"2-14":  {"Yön ve kaynak", "Bir yönü bulma ile kaynak ayırma temalarının bağlantısı. Hedefin anlamı ve emeğin nereye gittiği birlikte incelenebilir.", "Bir hedefin yanına zaman, beceri ve destek kaynaklarını yaz.", "Kaynaklarım seçtiğim yönü destekliyor mu?"},
	"3-60":  {"Değişim ve yeni düzen", "Yeni bir düzene geçiş ile mevcut sınırlar bağlantısı. Bir değişimin önce düzensiz başlayıp aşamalarla oluşması üzerine düşünülebilir; sürekli yenilik üretme zorunluluğu yoktur.", "Bir yeniliği küçük denemelerle geliştir ve sınırlarını belirt.", "Değişim için hangi koşulun oluşması gerekiyor?"},
	"4-63":  {"Soru ve mantıksal açıklama", "Sorgulama ile cevap oluşturma temalarının bağlantısı. Bir hipotezi açıkça kurup kanıtla sınamak için kullanılabilir.", "Bir soruyu, olası cevabı ve sınama yöntemini ayrı yaz.", "Bu cevap hangi sınamadan geçti?"},
	"5-15":  {"Ritim ve farklı tempolar", "Kişisel rutin ile farklı yaşam ritimlerine alan açma bağlantısı. Bir ortak düzende tempo farklarını konuşmak gözlem alanı olabilir.", "Kendi ritmini başkasının temposuyla karşılaştırmadan tarif et.", "Bu düzende farklı ritimler bir arada yaşayabiliyor mu?"},
	"6-59":  {"Yakınlık ve sınırlar", "Yakınlaşma ile duygusal sınır temalarının bağlantısı. Yakın ilişkinin niteliğini karşılıklı açıklık, rıza ve zaman üzerinden gözlemleyebilirsin; doğurganlık veya ilişki geleceği sonucu çıkarılmaz.", "Yakınlığı ve kişisel alan ihtiyacını birlikte konuş.", "Yakınlıkta iki tarafın sınırları da görünür mü?"},
	"7-31":  {"Ortak yön ve liderlik", "Grubun yönü ile duyulan yönlendirme bağlantısı. Liderlik unvanından çok önerinin ortak hedefle ve katılımla ilişkisi ele alınabilir.", "Bir yön önerisinde grubun katkısını ve karar alanlarını netleştir.", "Bu yön kimlerin katılımıyla oluşuyor?"},
	"9-52":  {"Odak ve duraklama", "Ayrıntıya dikkat ile durabilme bağlantısı. Bir işe yoğunlaşmak için koşul oluşturma teması öne çıkar.", "Dikkati bölen unsurları azalt ve tek bir bitirme ölçütü seç.", "Odaklanmam için hangi koşul gerekli?"},
	"10-20": {"Uyumlu ifadenin anı", "Kendinle uyumlu davranış ile şimdiki anın ifadesi bağlantısı. Söylediklerinin o anda kendi değerlerinle nasıl buluştuğunu gözlemleyebilirsin.", "Bir ifadenin yanında onunla uyumlu bir davranış örneği yaz.", "Sözüm ile davranışım aynı yönü gösteriyor mu?"},
	"10-34": {"Kendi yönünde hareket", "Kişisel davranış ile uygulama gücü bağlantısı. Gücünü dış beklentiye göre değil, seçtiğin uğraşlarla nasıl ilişkilendirdiğini gözlemleyebilirsin.", "Bir eforun kendi değerlerinle bağını yaz.", "Yaptığım şeyde kendi yönüm var mı?"},
	"10-57": {"Davranış ve anlık farkındalık", "Kendi tutumun ile içinde bulunulan anı fark etme bağlantısı. Somut bir karşılaşmada ilk fark edişin davranışına nasıl yansıdığını inceleyebilirsin.", "Bir olayın ilk izlenimini ve davranışını yan yana kaydet.", "Fark ettiğim işarete nasıl karşılık verdim?"},
	"11-56": {"Fikir ve hikâye", "Fikirleri deneyim ve anlatı yoluyla paylaşma bağlantısı. Bir hikâyenin yeni bir bakış sunması ile kesin kanıt oluşturmasını ayırmak önemlidir.", "Bir fikri anlaşılır bir örnekle paylaş; örneğin sınırını belirt.", "Bu anlatı dinleyene hangi bakışı açıyor?"},
	"12-22": {"Duygu ve uygun ifade", "Sosyal açıklık ile ifadenin zamanı bağlantısı. Duygusal deneyimin konuşmaya nasıl yansıdığını inceleyebilirsin. Bu kanal solar pleksusu tanımlar; karar yaklaşımı duygusal otorite bölümünden okunur.", "Önemli bir konuşmada kendi hazır oluşunu ve dinleyenin alanını kontrol et.", "Söylemek istediğimi hangi koşulda daha açık anlatabilirim?"},
	"13-33": {"Dinlemek ve deneyimi paylaşmak", "Tanıklık ile geri çekilip deneyimi sindirme bağlantısı. Bir anlatıyı saklamak, anlamlandırmak ve uygun zamanda paylaşmak üzerine düşünülebilir.", "Bir deneyimde sana ait olanı ve başka birinin mahremiyetini ayır.", "Bu hikâyeyi paylaşmak için uygun zaman ve izin var mı?"},
	"16-48": {"Derinlik ve beceri", "Derin bilgi ile uygulamayla gelişen beceri bağlantısı. Yeterlilik hissini somut çalışma ve geri bildirimle karşılaştırabilirsin.", "Bir beceri için küçük bir uygulama ve geri bildirim döngüsü kur.", "Bilgimi uygulamada ne kadar kullanabiliyorum?"},
	"17-62": {"Görüşü ayrıntıyla anlatmak", "Bir çerçeve oluşturma ile ayrıntılı ifade bağlantısı. Açıklamanın tutarlılığını, kanıtını ve dinleyenin ihtiyacını birlikte inceleyebilirsin.", "Bir görüşünü ana iddia ve üç dayanakla anlat.", "Ayrıntılarım görüşü anlaşılır mı kılıyor?"},
	"18-58": {"İyileştirme isteği", "Neyin düzeltilebileceğini fark etme ile geliştirme isteği bağlantısı. Eleştirinin zamanı, talep edilmesi ve uygulanabilirliği önem kazanabilir.", "Bir süreçte çalışan kısmı ve tek bir iyileştirme önerisini birlikte belirt.", "Düzeltme isteğim somut bir yarar sağlıyor mu?"},
	"19-49": {"İhtiyaç ve ilke", "İhtiyaçlara duyarlılık ile kabul sınırları bağlantısı. Bir toplulukta kimin ihtiyacının görüldüğünü ve hangi anlaşmanın geçerli olduğunu inceleyebilirsin.", "Bir ortaklıkta ihtiyacı, ilkeyi ve karşılıklı beklentiyi açıkça konuş.", "Bu düzenin ilkeleri ihtiyaçları gerçekten karşılıyor mu?"},
	"20-34": {"Anlık uygulama", "Şimdiki anın ifadesi ile uygulama gücü bağlantısı. Meşguliyet ile seçilmiş katkıyı ayırmak için kullanılabilir; kanal hızlı karar vermek zorunda olduğunu söylemez.", "Yaptığın işin amacını kısa bir cümleyle belirle ve otorite bölümünü esas al.", "Şu an yaptığım şey seçtiğim amaca hizmet ediyor mu?"},
	"20-57": {"Anlık farkındalığın ifadesi", "İnce fark ediş ile o anda ifade etme bağlantısı. İlk izlenimini söylemeden önce bağlamı ve dinleyenin alanını gözetebilirsin.", "Fark ettiğin işareti gözlem olarak anlat; kesin hükümle karıştırma.", "Söylediğim şey gözlem mi, yorum mu?"},
	"21-45": {"Ortak kaynağın yönetimi", "Kaynak üzerinde sorumluluk ile topluluk içinde paylaşım bağlantısı. Yönetimde yetki, katkı ve şeffaflık temaları birlikte ele alınabilir; maddi kazanç öngörülmez.", "Ortak bir kaynakta karar ve paylaşım kurallarını yazılı hale getir.", "Yönetim sorumluluğu ve beklentiler açık mı?"},
	"23-43": {"İçgörüyü anlaşılır kılmak", "Farklı bir içgörü ile onu sade anlatma bağlantısı. Bir fikrin yeniliği kadar ne zaman ve nasıl paylaşılacağı da gözlemlenebilir.", "Bir içgörüyü somut örnek ve kısa açıklamayla paylaş.", "Dinleyenin bağlamı bilmesi için ne gerekli?"},
	"24-61": {"Soruyu yeniden anlamlandırmak", "İçsel soru ile düşünceye geri dönme bağlantısı. Merakın yeni anlayış üretmesi ile aynı soruda sıkışmayı ayırmak bir gözlem alanıdır.", "Yeni bir bilgi getirmeyen düşünceye ara ver; cevapsız kısmı belirt.", "Bu düşünme süreci bana ne ekledi?"},
	"25-51": {"Alışılmışın dışına çıkmak", "Açık yüreklilik ile kendini sınama bağlantısı. Yeni bir deneyimin seni nasıl değiştirdiğini gözlemleyebilirsin; beklenmedik olayların kehaneti değildir.", "Bir denemenin amacını ve gerçek koşullarını açıklaştır.", "Bu adımda neyi keşfetmek istiyorum?"},
	"26-44": {"Örüntü ve etkili sunum", "Geçmiş örüntüleri tanıma ile ikna etme bağlantısı. Deneyimden öğrendiğini paylaşırken doğruluk ve verilen sözün sınırı birlikte incelenebilir.", "Bir önerinin dayandığı deneyimi ve bugünkü farkları belirt.", "Sunduğum vaat gerçek kapasiteyle örtüşüyor mu?"},
	"27-50": {"Bakım ve sorumluluk", "Destek verme ile koruyucu değerler bağlantısı. Bakımın kime, hangi kapsamda ve ne kadar kapasiteyle sunulduğunu gözlemleyebilirsin.", "Bir destek ilişkisinde sınırları ve diğer sorumluları konuş.", "Bakımın yükü adil paylaşılmış mı?"},
	"28-38": {"Anlamlı bir şeyi savunmak", "Mücadelede anlam arama ile değer verdiğini savunma bağlantısı. Her karşı çıkışın hangi amaca hizmet ettiğini inceleyebilirsin.", "Bir mücadelenin değerini ve sürdürme maliyetini yan yana yaz.", "Bu çaba benim için neden anlamlı?"},
	"29-46": {"Katılım içinde keşif", "Bir deneyime evet deme ile o deneyimde bulunma bağlantısı. Sonuca tutunmadan deneyimden öğrenmek ve katılım koşullarını değerlendirmek öne çıkabilir.", "Bir deneyime katılmadan önce kapsamı ve kapasiteni netleştir.", "Bu eveti gerçekten taşıyabilecek miyim?"},
	"30-41": {"Hayal ve deneyim arzusu", "Olasılığı hayal etme ile deneyimi isteme bağlantısı. Beklentiyle yaşanan gerçek deneyimi ayrı tutmak için kullanılabilir.", "Hayal ettiğin sonuç ile yaşayabileceğin farklı sonuçları birlikte düşün.", "Sonuç değişirse deneyime yine de katılmak ister miyim?"},
	"32-54": {"Gelişim ve süreklilik", "İlerleme isteği ile neyin sürdürülebileceğini fark etme bağlantısı. Gelişimi korunan değerler ve gerçek koşullarla birlikte ele alabilirsin.", "Bir ilerleme hedefinde korunması gereken şeyi belirle.", "Değişirken hangi değeri sürdürmek istiyorum?"},
	"34-57": {"Güç ve ince farkındalık", "Uygulama gücü ile anlık işaretleri fark etme bağlantısı. Bir uğraşta eforunla farkındalığının nasıl buluştuğunu gözlemleyebilirsin; sağlık veya güvenlik ölçümü yapılmaz.", "Bir işte fark ettiğin işaretleri ve verdiğin karşılığı kaydet.", "Eforumu ayırırken bulunduğum koşulu da fark ediyor muyum?"},
	"35-36": {"Yeni deneyimden öğrenmek", "Değişim isteği ile alışılmadık deneyimde öğrenme bağlantısı. Yoğun bir deneyimi hemen genellemeden sindirmek önem kazanabilir.", "Yeni bir durumun öncesindeki beklenti ile sonrasındaki öğrenmeyi karşılaştır.", "Bu deneyim gerçekten ne öğretti?"},
	"37-40": {"Anlaşma ve karşılıklılık", "Yakın çevrede destek ile emek ve dinlenme bağlantısı. Bir ilişkinin sözlü olmayan beklentilerini açık anlaşmalara dönüştürmek için kullanılabilir.", "Ortak bir işte emek, karşılık ve kişisel zaman koşullarını konuş.", "Bu anlaşmada hem katkı hem dinlenme alanı var mı?"},
	"39-55": {"Duygusal anlamı görünür kılmak", "Duygusal hareket yaratma ile deneyime anlam verme bağlantısı. Duyguların bir karşılaşmayla nasıl değiştiğini gözlemleyebilirsin; başkasını zorlamak gerektiği sonucu çıkarılmaz.", "Zor bir duygusal konuyu uygun zaman ve karşılıklı rızayla aç.", "Bu karşılaşma hangi duyguyu veya ihtiyacı görünür kıldı?"},
	"42-53": {"Başlangıç ve tamamlanma", "Bir döngüyü başlatma ile süreci tamamlama bağlantısı. Bir işin hangi aşamasında bulunduğunu ve bitirme koşullarını değerlendirebilirsin.", "Bir projenin başlangıç, gelişme ve tamamlanma ölçütlerini yaz.", "Bu süreç hangi aşamada?"},
	"47-64": {"İzlenimlerden anlayışa", "Dağınık izlenimler ile yaşananı anlamlandırma bağlantısı. Geçmişi tek bir açıklamaya zorlamadan, zaman içinde beliren bağlantıları inceleyebilirsin.", "Bir olayın parçalarını yorum katmadan kaydet ve sonra yeniden oku.", "Anlayışım yeni bilgiyle nasıl değişti?"},
}
